from __future__ import annotations


ADMIN_PAGE = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Joker QQ Admin</title>
<style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e9eef8;background:#0d1728;--bg:#101b2e;--panel:#14233a;--line:#28415f;--muted:#8ea5c4;--accent:#16b9b3;--accent2:#ff7a45}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#0c1728,#101d34 54%,#0b2234);min-height:100vh}.shell{display:grid;grid-template-columns:252px minmax(0,1fr);min-height:100vh}.side{background:#0c182bd9;border-right:1px solid var(--line);padding:25px 16px;display:flex;flex-direction:column;gap:21px}.brand{padding:0 12px}.brand strong{font-size:20px}.brand span,.muted{display:block;color:var(--muted);font-size:12px;line-height:1.6;margin-top:6px}.nav-section{border-top:1px solid #203750;padding-top:14px}.nav-title{color:#a6b8d0;font-size:12px;padding:0 12px 7px}.nav button{width:100%;border:0;background:transparent;color:#c0ccdb;text-align:left;border-radius:8px;padding:10px 12px;margin:2px 0;cursor:pointer;font:inherit}.nav button:hover,.nav button.active{background:#173754;color:#fff;box-shadow:inset 2px 0 var(--accent)}.side-foot{margin-top:auto;padding:0 12px}.side-foot button,.button{border:1px solid #31516e;background:#1a314d;color:#eff7ff;border-radius:7px;padding:9px 12px;font:inherit;cursor:pointer}.button.primary{background:var(--accent);border-color:var(--accent);color:#042327;font-weight:700}.button.warn{background:#47302b;border-color:#764638;color:#ffd0c0}.button:hover{filter:brightness(1.1)}.main{min-width:0}.top{padding:21px 32px;border-bottom:1px solid var(--line);background:#101d30bf;display:flex;justify-content:space-between;align-items:center;gap:16px}.top h1{font-size:22px;margin:0}.top p{margin:6px 0 0;color:var(--muted);font-size:13px}.status{color:#75e5bf;font-size:13px}.content{max-width:1320px;margin:auto;padding:28px 32px 56px}.view{display:none}.view.active{display:block}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.card,.panel{background:#13243bde;border:1px solid var(--line);border-radius:10px;box-shadow:0 10px 25px #02091435}.card{padding:18px}.card strong{font-size:26px;display:block;margin-top:9px}.panel{padding:20px;margin-top:18px}.panel h2{margin:0;font-size:16px}.panel-head{display:flex;justify-content:space-between;align-items:start;gap:15px;margin-bottom:16px}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:end}label{display:grid;gap:6px;color:#a6b8d0;font-size:12px}input,select{width:100%;padding:10px;border:1px solid #365574;background:#0e1c2f;color:#edf6ff;border-radius:7px;font:inherit}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid #28415f;vertical-align:top}th{color:#98b0ce}.empty{padding:24px;color:var(--muted);text-align:center}.pill{display:inline-block;border-radius:99px;padding:3px 8px;background:#16473f;color:#85ebc7;font-size:12px}.pill.off{background:#432e35;color:#ffb4bd}.notice{border-left:3px solid var(--accent);background:#103044;padding:11px 13px;color:#c7e9ed;font-size:13px;line-height:1.6;border-radius:5px}@media(max-width:880px){.shell{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.nav button{min-width:max-content}.grid,.form{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding:22px 18px}.top{padding:18px}.side-foot{display:none}}@media(max-width:560px){.grid,.form{grid-template-columns:1fr}table{display:block;overflow:auto;white-space:nowrap}}
</style></head><body><div class="shell"><aside class="side"><div class="brand"><strong>Joker QQ Admin</strong><span>官方 QQ 机器人管理端</span></div><div class="nav-section"><div class="nav-title">管理中心</div><nav class="nav"><button class="active" data-view="overview">概览</button><button data-view="cards">授权卡密</button><button data-view="users">注册用户</button></nav></div><div class="nav-section"><div class="nav-title">全局设置</div><nav class="nav"><button data-view="service">机器人与接口</button><button data-view="email">邮箱与注册</button></nav></div><div class="nav-section"><div class="nav-title">运行</div><nav class="nav"><button data-view="runtime">服务状态</button></nav></div><div class="side-foot"><span class="muted" id="admin-label">管理员</span><button id="logout">退出登录</button></div></aside><main class="main"><header class="top"><div><h1 id="title">概览</h1><p id="subtitle">统一管理账号、卡密和官方机器人服务。</p></div><span class="status" id="status">正在检查服务</span></header><div class="content">
<section class="view active" id="overview"><div class="grid"><div class="card"><span class="muted">注册用户</span><strong id="metric-users">-</strong></div><div class="card"><span class="muted">已授权群</span><strong id="metric-groups">-</strong></div><div class="card"><span class="muted">有效卡密</span><strong id="metric-cards">-</strong></div><div class="card"><span class="muted">网关状态</span><strong id="metric-gateway">-</strong></div></div><div class="panel"><h2>使用方式</h2><p class="muted">先生成用户注册卡，客户注册后再由客户用群授权卡绑定官方群。卡密不预先绑定任何群；每个群只能绑定一个分群账号。</p></div></section>
<section class="view" id="cards"><div class="panel"><div class="panel-head"><div><h2>生成授权卡密</h2><p class="muted">用户注册卡用于创建客户账号；群授权卡由客户登录后绑定官方群；QQ 用户授权卡用于群内 <code>/授权 卡密</code>。</p></div></div><div class="form"><label>卡密类型<select id="card-kind"><option value="portal">用户注册卡</option><option value="group">群授权卡</option><option value="bot">QQ 用户授权卡</option></select></label><label>有效天数<input id="card-days" type="number" min="1" value="30"></label><label>可使用次数<input id="card-uses" type="number" min="1" value="1"></label><button class="button primary" id="create-card">生成卡密</button></div><p class="muted" id="card-result"></p></div><div class="panel"><h2>卡密列表</h2><div id="cards-table"></div></div></section>
<section class="view" id="users"><div class="panel"><div class="panel-head"><div><h2>注册用户</h2><p class="muted">查看分群用户、已绑定群，并可停用账号或重置客户密码。</p></div></div><div id="users-table"></div></div></section>
<section class="view" id="service"><div class="panel"><div class="panel-head"><div><h2>官方机器人接口</h2><p class="muted">这里只管理全局连接信息；不会覆盖任意分群的功能设置。</p></div></div><div class="form"><label>AppID<input id="setting-app-id"></label><label>接收方式<select id="setting-transport"><option value="webhook">Webhook</option><option value="websocket">WebSocket</option></select></label><label>官方 API 地址<input id="setting-api-base"></label><label>管理后台路径<input id="setting-admin-path"></label><label>用户中心路径<input id="setting-user-path"></label><label>控制台端口<input id="setting-port" type="number"></label><button class="button primary" id="save-service">保存并重启</button></div><p class="muted" id="service-result"></p></div></section>
<section class="view" id="email"><div class="panel"><div class="panel-head"><div><h2>邮箱与注册</h2><p class="muted">用户注册必须完成邮箱验证码验证。密码不会在页面显示。</p></div></div><div class="form"><label>SMTP 地址<input id="smtp-host"></label><label>SMTP 端口<input id="smtp-port" type="number"></label><label>发件邮箱<input id="smtp-from"></label><label>SMTP 用户名<input id="smtp-user"></label><label>SMTP 密码<input id="smtp-password" type="password" placeholder="留空保持不变"></label><label>注册邮箱验证<select id="registration-email" disabled><option value="1">固定开启</option></select></label><button class="button primary" id="save-email">保存并重启</button></div><p class="muted" id="email-result"></p></div></section>
<section class="view" id="runtime"><div class="panel"><div class="panel-head"><div><h2>服务状态</h2><p class="muted" id="runtime-info">正在读取</p></div><button class="button warn" id="restart">重启官方机器人服务</button></div><div class="notice">重启只影响 QQ 官方机器人服务，不会修改分群配置或卡密数据。</div></div></section>
</div></main></div><script>
const api=async(u,o={})=>{const r=await fetch(u,{...o,headers:{'Content-Type':'application/json',...(o.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'操作失败');return d};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let settings={};const setView=view=>{document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===view));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));const labels={overview:['概览','统一管理账号、卡密和官方机器人服务。'],cards:['授权卡密','卡密独立生成，用户在对应位置使用。'],users:['注册用户','管理分群用户与其已绑定群。'],service:['机器人与接口','全局连接配置。'],email:['邮箱与注册','注册与邮件通知配置。'],runtime:['服务状态','检查机器人进程和网关。']};document.getElementById('title').textContent=labels[view][0];document.getElementById('subtitle').textContent=labels[view][1]};document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));
const cardKind={portal:'用户注册卡',group:'群授权卡',bot:'QQ 用户授权卡'};const renderCards=cards=>{document.getElementById('cards-table').innerHTML=cards.length?`<table><thead><tr><th>卡密</th><th>类型</th><th>使用</th><th>有效期</th><th>状态</th><th></th></tr></thead><tbody>${cards.map(x=>`<tr><td>${esc(x.card_code)}</td><td>${cardKind[x.kind]||esc(x.kind)}</td><td>${x.used_count}/${x.max_uses}</td><td>${new Date(x.expires_at*1000).toLocaleString()}</td><td><span class="pill ${x.enabled?'':'off'}">${x.enabled?'有效':'已停用'}</span></td><td>${x.enabled?`<button class="button" data-revoke="${esc(x.card_code)}">停用</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无卡密</div>';document.querySelectorAll('[data-revoke]').forEach(x=>x.onclick=async()=>{await api('/api/auth/revoke-card',{method:'POST',body:JSON.stringify({card_code:x.dataset.revoke})});load()})};const renderUsers=data=>{const rows=data.dashboard_users.filter(x=>x.role==='group');document.getElementById('users-table').innerHTML=rows.length?`<table><thead><tr><th>账号</th><th>邮箱</th><th>已授权群</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.display_name||x.username)}<br><span class="muted">${esc(x.username)}</span></td><td>${esc(x.email||'-')}</td><td>${(x.groups||[]).map(g=>esc(g.numeric_group_id||g.scope_id)).join('<br>')||'-'}</td><td><span class="pill ${x.enabled?'':'off'}">${x.enabled?'启用':'停用'}</span></td><td>${esc(x.created_at)}</td><td><button class="button" data-password="${x.user_id}">改密码</button> <button class="button" data-user-toggle="${x.user_id}" data-next="${x.enabled?'0':'1'}">${x.enabled?'停用':'启用'}</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无注册用户</div>';document.querySelectorAll('[data-password]').forEach(x=>x.onclick=async()=>{const password=prompt('输入新密码（至少 6 位）');if(password)await api('/api/auth/users/update',{method:'POST',body:JSON.stringify({user_id:+x.dataset.password,password})})});document.querySelectorAll('[data-user-toggle]').forEach(x=>x.onclick=async()=>{await api('/api/auth/users/update',{method:'POST',body:JSON.stringify({user_id:+x.dataset.userToggle,enabled:x.dataset.next==='1'})});load()})};
const fillSettings=s=>{settings=s;for(const [id,key] of [['setting-app-id','app_id'],['setting-transport','transport'],['setting-api-base','api_base_url'],['setting-admin-path','admin_path'],['setting-user-path','user_path'],['setting-port','dashboard_port'],['smtp-host','smtp_host'],['smtp-port','smtp_port'],['smtp-from','smtp_from'],['smtp-user','smtp_username']])document.getElementById(id).value=String(s[key]??'');};const saveSettings=async(kind)=>{const p={...settings,app_id:document.getElementById('setting-app-id').value.trim(),transport:document.getElementById('setting-transport').value,api_base_url:document.getElementById('setting-api-base').value.trim(),admin_path:document.getElementById('setting-admin-path').value.trim(),user_path:document.getElementById('setting-user-path').value.trim(),dashboard_port:+document.getElementById('setting-port').value,smtp_host:document.getElementById('smtp-host').value.trim(),smtp_port:+document.getElementById('smtp-port').value,smtp_from:document.getElementById('smtp-from').value.trim(),smtp_username:document.getElementById('smtp-user').value.trim(),smtp_password:document.getElementById('smtp-password').value,registration_require_email:true,smtp_use_tls:!!settings.smtp_use_tls};await api('/api/settings',{method:'POST',body:JSON.stringify(p)});document.getElementById(kind+'-result').textContent='已保存，服务正在重启。'};
async function load(){try{const [me,status,cards,users,power,config]=await Promise.all([api('/api/auth/me'),api('/api/status'),api('/api/auth/cards'),api('/api/auth/users'),api('/api/power'),api('/api/settings')]);document.getElementById('admin-label').textContent=me.display_name||me.username;document.getElementById('status').textContent=status.gateway_state||'已连接';document.getElementById('metric-users').textContent=users.dashboard_users.filter(x=>x.role==='group').length;document.getElementById('metric-groups').textContent=status.group_count;document.getElementById('metric-cards').textContent=cards.filter(x=>x.enabled).length;document.getElementById('metric-gateway').textContent=power.enabled?'运行中':'已关闭';document.getElementById('runtime-info').textContent=`网关：${status.gateway_state||'-'}；事件：${status.event_count||0}；回复：${status.reply_count||0}${status.last_error?'；错误：'+status.last_error:''}`;renderCards(cards);renderUsers(users);fillSettings(config)}catch(e){document.getElementById('status').textContent=e.message}}
document.getElementById('create-card').onclick=async()=>{const r=await api('/api/auth/cards',{method:'POST',body:JSON.stringify({kind:document.getElementById('card-kind').value,days:+document.getElementById('card-days').value,max_uses:+document.getElementById('card-uses').value})});document.getElementById('card-result').textContent='新卡密：'+r.card_code;load()};document.getElementById('save-service').onclick=()=>saveSettings('service');document.getElementById('save-email').onclick=()=>saveSettings('email');document.getElementById('restart').onclick=async()=>{await api('/api/restart',{method:'POST',body:'{}'});document.getElementById('runtime-info').textContent='已请求重启服务。'};document.getElementById('logout').onclick=async()=>{await fetch('__LOGOUT_ENDPOINT__',{method:'POST'});location.href='/'};load();
</script></body></html>"""


ADMIN_PAGE = (
    ADMIN_PAGE.replace(
        '<section class="view" id="cards"><div class="panel"><div class="panel-head"><div><h2>生成授权卡密</h2><p class="muted">用户注册卡用于创建客户账号；群授权卡由客户登录后绑定官方群；QQ 用户授权卡用于群内 <code>/授权 卡密</code>。</p></div></div><div class="form"><label>卡密类型<select id="card-kind"><option value="portal">用户注册卡</option><option value="group">群授权卡</option><option value="bot">QQ 用户授权卡</option></select></label><label>有效天数<input id="card-days" type="number" min="1" value="30"></label><label>可使用次数<input id="card-uses" type="number" min="1" value="1"></label><button class="button primary" id="create-card">生成卡密</button></div><p class="muted" id="card-result"></p></div><div class="panel"><h2>卡密列表</h2><div id="cards-table"></div></div></section>',
        '<section class="view" id="cards"><div class="panel"><div class="panel-head"><div><h2>生成官方群授权卡</h2><p class="muted">每张授权卡只能绑定一个官方群。群授权到期后，该群不再执行机器人功能。</p></div></div><div class="form"><label>有效天数<input id="card-days" type="number" min="1" value="30"></label><label>可授权群数<input id="card-uses" type="number" min="1" value="1" disabled></label><div><button class="button primary" id="create-card">生成授权卡</button></div></div><p class="muted" id="card-result"></p></div><div class="panel"><h2>官方群授权卡</h2><div id="cards-table"></div></div></section>',
    )
    .replace(
        "const cardKind={portal:'用户注册卡',group:'群授权卡',bot:'QQ 用户授权卡'};",
        "const cardKind={license:'机器人授权卡',portal:'旧注册卡',group:'旧群授权卡',bot:'旧 QQ 用户卡'};",
    )
    .replace(
        "<td>${x.enabled?`<button class=\"button\" data-revoke=\"${esc(x.card_code)}\">停用</button>`:''}</td>",
        "<td>${x.enabled?`<button class=\"button\" data-revoke=\"${esc(x.card_code)}\">停用</button>`:'<span class=\"muted\">已停用</span>'} <button class=\"button danger\" data-delete-card=\"${esc(x.card_code)}\">删除</button></td>",
    )
    .replace(
        "load()})};const renderUsers",
        "load()})};document.querySelectorAll('[data-delete-card]').forEach(x=>x.onclick=async()=>{if(!confirm('确认删除该授权卡？已绑定此卡的客户将不能继续绑定新官方群。'))return;await api('/api/auth/cards/delete',{method:'POST',body:JSON.stringify({card_code:x.dataset.deleteCard})});load()});const renderUsers",
    )
    .replace(
        "body:JSON.stringify({kind:document.getElementById('card-kind').value,days:+document.getElementById('card-days').value,max_uses:+document.getElementById('card-uses').value})",
        "body:JSON.stringify({kind:'license',days:+document.getElementById('card-days').value,max_uses:+document.getElementById('card-uses').value})",
    )
)

GROUP_PAGE = r"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Joker QQ · 用户中心</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#e9eef8;background:#0d1728;--bg:#101b2e;--panel:#14233a;--line:#28415f;--muted:#8ea5c4;--accent:#16b9b3;--warn:#ff7a45}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#0c1728,#10233a 56%,#0b1d31);min-height:100vh}.shell{display:grid;grid-template-columns:252px minmax(0,1fr);min-height:100vh}.side{background:#0c182bd9;border-right:1px solid var(--line);padding:25px 16px;display:flex;flex-direction:column;gap:20px}.brand{padding:0 12px}.brand strong{font-size:20px}.brand span,.muted{display:block;color:var(--muted);font-size:12px;line-height:1.6;margin-top:6px}.nav-section{border-top:1px solid #203750;padding-top:14px}.nav-title{color:#a6b8d0;font-size:12px;padding:0 12px 7px}.nav button{width:100%;border:0;background:transparent;color:#c0ccdb;text-align:left;border-radius:8px;padding:10px 12px;margin:2px 0;cursor:pointer;font:inherit}.nav button:hover,.nav button.active{background:#173754;color:#fff;box-shadow:inset 2px 0 var(--accent)}.side-foot{margin-top:auto;padding:0 12px}.side-foot button,.button{border:1px solid #31516e;background:#1a314d;color:#eff7ff;border-radius:7px;padding:9px 12px;font:inherit;cursor:pointer}.button.primary{background:var(--accent);border-color:var(--accent);color:#042327;font-weight:700}.button.danger{background:#472b34;border-color:#76414d;color:#ffc6cd}.button:hover{filter:brightness(1.1)}.main{min-width:0}.top{padding:19px 32px;border-bottom:1px solid var(--line);background:#101d30bf;display:flex;justify-content:space-between;align-items:center;gap:16px}.top h1{font-size:22px;margin:0}.top p{margin:6px 0 0;color:var(--muted);font-size:13px}.top select{width:min(360px,48vw)}.content{max-width:1320px;margin:auto;padding:28px 32px 56px}.view{display:none}.view.active{display:block}.panel{background:#13243bde;border:1px solid var(--line);border-radius:10px;box-shadow:0 10px 25px #02091435;padding:20px;margin-bottom:18px}.panel h2{margin:0;font-size:16px}.panel-head{display:flex;justify-content:space-between;align-items:start;gap:15px;margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{border:1px solid #31516e;background:#10243c;border-radius:9px;padding:16px}.card strong{font-size:20px;display:block;margin-top:7px}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;align-items:end}label{display:grid;gap:6px;color:#a6b8d0;font-size:12px}input,select,textarea{width:100%;padding:10px;border:1px solid #365574;background:#0e1c2f;color:#edf6ff;border-radius:7px;font:inherit}textarea{min-height:84px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid #28415f;vertical-align:top}th{color:#98b0ce}.empty{padding:24px;color:var(--muted);text-align:center}.notice{border-left:3px solid var(--accent);background:#103044;padding:11px 13px;color:#c7e9ed;font-size:13px;line-height:1.6;border-radius:5px}.toggle-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.toggle{display:flex;align-items:center;gap:8px;padding:10px;background:#10243c;border:1px solid #254966;border-radius:7px;color:#dcecff;font-size:13px}.toggle input{width:auto}.tag{display:inline-block;border-radius:99px;padding:3px 8px;background:#16473f;color:#85ebc7;font-size:12px}@media(max-width:880px){.shell{grid-template-columns:1fr}.side{border-right:0;border-bottom:1px solid var(--line)}.nav{display:flex;overflow:auto}.nav button{min-width:max-content}.grid,.form,.toggle-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.content{padding:22px 18px}.top{padding:18px}.side-foot{display:none}}@media(max-width:560px){.grid,.form,.toggle-grid{grid-template-columns:1fr}table{display:block;overflow:auto;white-space:nowrap}}
</style></head><body><div class="shell"><aside class="side"><div class="brand"><strong>Joker 用户中心</strong><span>只管理你已授权的官方群</span></div><div class="nav-section"><div class="nav-title">群组</div><nav class="nav"><button class="active" data-view="groups">我的群</button><button data-view="bind">绑定群授权</button></nav></div><div class="nav-section"><div class="nav-title">群管</div><nav class="nav"><button data-view="settings">基础设置</button><button data-view="replies">自动回复</button><button data-view="blacklist">黑名单</button></nav></div><div class="nav-section"><div class="nav-title">关键词审核</div><nav class="nav"><button data-view="keyword-mute">关键词禁言</button><button data-view="keyword-kick">关键词踢出</button><button data-view="keyword-blacklist">关键词拉黑</button></nav></div><div class="nav-section"><div class="nav-title">数据与账号</div><nav class="nav"><button data-view="messages">群消息记录</button><button data-view="profile">账号资料</button></nav></div><div class="side-foot"><span class="muted" id="user-label">登录中</span><button id="logout">退出登录</button></div></aside><main class="main"><header class="top"><div><h1 id="title">我的群</h1><p id="subtitle">选择一个已授权群后进行配置。</p></div><select id="scope-switch" aria-label="当前群"><option value="">尚未选择群</option></select></header><div class="content">
<section class="view active" id="groups"><div class="panel"><div class="panel-head"><div><h2>已绑定群</h2><p class="muted">每个群只能绑定一个分群账号。绑定完成后可在此选择群并保存设置。</p></div><button class="button primary" data-view="bind">绑定新群</button></div><div id="groups-list" class="grid"></div></div></section>
<section class="view" id="bind"><div class="panel"><div class="panel-head"><div><h2>绑定群授权</h2><p class="muted">输入官方群 OpenID 与管理员发放的群授权卡。卡密本身不预先绑定群。</p></div></div><div class="form"><label>官方群 OpenID<input id="bind-scope" placeholder="官方群 group_openid"></label><label>群授权卡<input id="bind-card" placeholder="JOKER-XXXXXXXXXX"></label><button class="button primary" id="bind-group">绑定当前群</button></div><p class="muted" id="bind-result"></p></div></section>
<section class="view" id="settings"><div class="panel"><div class="panel-head"><div><h2>基础设置</h2><p class="muted">此处只影响顶部选择的当前群。关键词审核规则在单独的导航中设置。</p></div><button class="button primary" id="save-settings">保存当前群设置</button></div><div class="form"><label>SCUM 服务器 ID<input id="server-id"></label><label>自动回复<select id="auto-reply"><option value="1">开启</option><option value="0">关闭</option></select></label></div><div id="feature-toggles" class="toggle-grid" style="margin-top:14px"></div><p id="settings-result" class="muted"></p></div></section>
<section class="view" id="replies"><div class="panel"><div class="panel-head"><div><h2>自动回复</h2><p class="muted">本页只管理当前群的自动回复。</p></div></div><div class="form"><label>关键词<input id="reply-trigger"></label><label>回复内容<textarea id="reply-response"></textarea></label><button class="button primary" id="save-reply">保存回复</button></div></div><div class="panel"><div id="reply-list"></div></div></section>
<section class="view" id="keyword-mute"><div class="panel"><div class="panel-head"><div><h2>关键词禁言</h2><p class="muted">命中后对发言成员执行官方禁言接口。</p></div></div><div class="form"><label>触发关键词<input data-rule-trigger="mute"></label><label>禁言分钟<input data-rule-minutes="mute" type="number" min="1" value="10"></label><button class="button primary" data-rule-save="mute">添加禁言规则</button></div></div><div class="panel"><div id="rules-mute"></div></div></section>
<section class="view" id="keyword-kick"><div class="panel"><div class="panel-head"><div><h2>关键词踢出</h2><p class="muted">命中后对发言成员执行官方移除成员接口。</p></div></div><div class="form"><label>触发关键词<input data-rule-trigger="kick"></label><button class="button primary" data-rule-save="kick">添加踢出规则</button></div></div><div class="panel"><div id="rules-kick"></div></div></section>
<section class="view" id="keyword-blacklist"><div class="panel"><div class="panel-head"><div><h2>关键词拉黑</h2><p class="muted">命中后将成员移出群并加入官方群黑名单。</p></div></div><div class="form"><label>触发关键词<input data-rule-trigger="blacklist"></label><button class="button primary" data-rule-save="blacklist">添加拉黑规则</button></div></div><div class="panel"><div id="rules-blacklist"></div></div></section>
<section class="view" id="blacklist"><div class="panel"><div class="panel-head"><div><h2>群黑名单</h2><p class="muted">加入黑名单会通过官方接口移出该成员并拉黑。</p></div></div><div class="form"><label>成员 OpenID<input id="black-user"></label><label>原因<input id="black-reason" placeholder="可选"></label><button class="button danger" id="add-black">加入黑名单</button></div></div><div class="panel"><div id="black-list"></div></div></section>
<section class="view" id="messages"><div class="panel"><div class="panel-head"><div><h2>群消息记录</h2><p class="muted">仅显示机器人已收到并记录的文字消息。</p></div><button class="button" id="reload-messages">刷新</button></div><div id="message-list"></div></div></section>
<section class="view" id="profile"><div class="panel"><div class="panel-head"><div><h2>账号资料</h2><p class="muted">修改个人展示名与邮箱不会影响群授权。</p></div></div><div class="form"><label>账号<input id="profile-username" disabled></label><label>显示名称<input id="profile-name"></label><label>邮箱<input id="profile-email" type="email"></label><button class="button primary" id="save-profile">保存资料</button></div><p class="muted" id="profile-result"></p></div></section>
</div></main></div><script>
const api=async(u,o={})=>{const r=await fetch(u,{...o,headers:{'Content-Type':'application/json',...(o.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'操作失败');return d};const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let me={},groups=[],scope='',config={};const noGroup=()=>{alert('请先在“绑定群授权”中绑定官方群。');return false};const groupNeeded=fn=>async()=>{if(!scope)return noGroup();return fn()};const labels={groups:['我的群','选择一个已授权群后进行配置。'],bind:['绑定群授权','使用群授权卡绑定你要管理的官方群。'],settings:['基础设置','只影响顶部当前选择的群。'],replies:['自动回复','当前群的关键词回复。'],blacklist:['黑名单','当前群的成员黑名单。'],'keyword-mute':['关键词禁言','独立规则，独立设置。'],'keyword-kick':['关键词踢出','独立规则，独立设置。'],'keyword-blacklist':['关键词拉黑','独立规则，独立设置。'],messages:['群消息记录','当前群已收到的文字消息。'],profile:['账号资料','管理你的登录资料。']};const setView=v=>{document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===v));document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v));document.getElementById('title').textContent=labels[v][0];document.getElementById('subtitle').textContent=labels[v][1];if(v==='messages')loadMessages();if(v==='blacklist')loadBlacklist()};document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>setView(x.dataset.view));
const setupGroups=()=>{const select=document.getElementById('scope-switch');select.innerHTML='<option value="">选择当前群</option>'+groups.map(g=>`<option value="${esc(g.scope_id)}" ${g.scope_id===scope?'selected':''}>${esc(g.numeric_group_id||g.scope_id)}</option>`).join('');document.getElementById('groups-list').innerHTML=groups.length?groups.map(g=>`<button class="card" data-pick="${esc(g.scope_id)}" style="text-align:left;color:inherit;cursor:pointer"><span class="muted">官方群</span><strong>${esc(g.numeric_group_id||g.scope_id)}</strong><span class="muted">服务器：${esc(g.server_id||'未绑定')} · 消息：${g.message_count||0}</span></button>`).join(''):'<div class="empty">尚未绑定群授权</div>';document.querySelectorAll('[data-pick]').forEach(x=>x.onclick=()=>{scope=x.dataset.pick;setupGroups();loadGroup()});select.onchange=()=>{scope=select.value;loadGroup()}};
const renderSettings=()=>{document.getElementById('server-id').value=config.server_id||'';document.getElementById('auto-reply').value=config.auto_reply_enabled?'1':'0';const hidden=new Set(['keyword_mute','keyword_kick','keyword_blacklist','auto_reply']);const features=(config.features||[]).filter(f=>!hidden.has(f.key));document.getElementById('feature-toggles').innerHTML=features.map(f=>`<label class="toggle"><input type="checkbox" data-feature="${esc(f.key)}" ${f.enabled?'checked':''}>${esc(f.label)}</label>`).join('')||'<div class="empty">暂无可配置功能</div>'};const loadGroup=async()=>{if(!scope){config={};return}try{config=await api('/api/group-config?scope_id='+encodeURIComponent(scope));renderSettings();await Promise.all([loadReplies(),loadRules('mute'),loadRules('kick'),loadRules('blacklist')])}catch(e){alert(e.message)}};
const loadReplies=async()=>{if(!scope)return;const rows=await api('/api/replies?scope_id='+encodeURIComponent(scope));document.getElementById('reply-list').innerHTML=rows.length?`<table><thead><tr><th>关键词</th><th>回复</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.trigger)}</td><td>${esc(r.response)}</td><td><button class="button danger" data-del-reply="${esc(r.trigger)}">删除</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无自动回复</div>';document.querySelectorAll('[data-del-reply]').forEach(x=>x.onclick=groupNeeded(async()=>{await api('/api/replies/delete',{method:'POST',body:JSON.stringify({scope_id:scope,trigger:x.dataset.delReply})});loadReplies()}))};const loadRules=async action=>{if(!scope)return;const rows=await api('/api/keyword-rules?scope_id='+encodeURIComponent(scope)+'&action='+action);const target=document.getElementById('rules-'+action);target.innerHTML=rows.length?`<table><thead><tr><th>关键词</th><th>${action==='mute'?'禁言时长':'动作'}</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.trigger)}</td><td>${action==='mute'?r.duration_minutes+' 分钟':action==='kick'?'踢出':'拉黑'}</td><td><button class="button danger" data-del-rule="${r.rule_id}" data-action="${action}">删除</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无规则</div>';target.querySelectorAll('[data-del-rule]').forEach(x=>x.onclick=groupNeeded(async()=>{await api('/api/keyword-rules/delete',{method:'POST',body:JSON.stringify({scope_id:scope,rule_id:+x.dataset.delRule})});loadRules(x.dataset.action)}))};
const loadBlacklist=async()=>{if(!scope){document.getElementById('black-list').innerHTML='<div class="empty">请先选择群</div>';return}try{const rows=await api('/api/blacklist?scope_id='+encodeURIComponent(scope));document.getElementById('black-list').innerHTML=rows.length?`<table><thead><tr><th>成员 OpenID</th><th>原因</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.user_id)}</td><td>${esc(r.reason||'-')}</td><td><button class="button" data-unblack="${esc(r.user_id)}">移出黑名单</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无黑名单记录</div>';document.querySelectorAll('[data-unblack]').forEach(x=>x.onclick=groupNeeded(async()=>{await api('/api/blacklist',{method:'POST',body:JSON.stringify({scope_id:scope,user_id:x.dataset.unblack,action:'remove'})});loadBlacklist()}))}catch(e){document.getElementById('black-list').innerHTML='<div class="empty">'+esc(e.message)+'</div>'}};const loadMessages=async()=>{if(!scope){document.getElementById('message-list').innerHTML='<div class="empty">请先选择群</div>';return}const rows=await api('/api/messages?scope_id='+encodeURIComponent(scope));document.getElementById('message-list').innerHTML=rows.length?`<table><thead><tr><th>时间</th><th>成员</th><th>内容</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.created_at)}</td><td>${esc(r.user_id)}</td><td>${esc(r.content)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">暂无已记录消息</div>'};
document.getElementById('bind-group').onclick=async()=>{try{const r=await api('/api/user/groups/bind',{method:'POST',body:JSON.stringify({scope_id:document.getElementById('bind-scope').value.trim(),card_code:document.getElementById('bind-card').value.trim()})});document.getElementById('bind-result').textContent=r.already_bound?'该群已绑定到当前账号。':'群授权已绑定。';document.getElementById('bind-card').value='';await load();scope=r.scope_id;setupGroups();loadGroup()}catch(e){document.getElementById('bind-result').textContent=e.message}};document.getElementById('save-settings').onclick=groupNeeded(async()=>{const features={};document.querySelectorAll('[data-feature]').forEach(x=>features[x.dataset.feature]=x.checked);await api('/api/group-config',{method:'POST',body:JSON.stringify({scope_id:scope,features,server_id:document.getElementById('server-id').value.trim(),auto_reply_enabled:document.getElementById('auto-reply').value==='1'})});document.getElementById('settings-result').textContent='当前群设置已保存。';loadGroup()});document.getElementById('save-reply').onclick=groupNeeded(async()=>{await api('/api/replies',{method:'POST',body:JSON.stringify({scope_id:scope,trigger:document.getElementById('reply-trigger').value.trim(),response:document.getElementById('reply-response').value.trim()})});document.getElementById('reply-trigger').value='';document.getElementById('reply-response').value='';loadReplies()});document.querySelectorAll('[data-rule-save]').forEach(x=>x.onclick=groupNeeded(async()=>{const action=x.dataset.ruleSave;const trigger=document.querySelector(`[data-rule-trigger="${action}"]`).value.trim();const minutes=document.querySelector(`[data-rule-minutes="${action}"]`)?.value||10;await api('/api/keyword-rules',{method:'POST',body:JSON.stringify({scope_id:scope,action,trigger,duration_minutes:+minutes})});document.querySelector(`[data-rule-trigger="${action}"]`).value='';loadRules(action)}));document.getElementById('add-black').onclick=groupNeeded(async()=>{await api('/api/blacklist',{method:'POST',body:JSON.stringify({scope_id:scope,user_id:document.getElementById('black-user').value.trim(),reason:document.getElementById('black-reason').value.trim()})});document.getElementById('black-user').value='';document.getElementById('black-reason').value='';loadBlacklist()});document.getElementById('reload-messages').onclick=()=>loadMessages();document.getElementById('save-profile').onclick=async()=>{await api('/api/profile',{method:'POST',body:JSON.stringify({display_name:document.getElementById('profile-name').value.trim(),email:document.getElementById('profile-email').value.trim()})});document.getElementById('profile-result').textContent='资料已保存。'};document.getElementById('logout').onclick=async()=>{await fetch('__LOGOUT_ENDPOINT__',{method:'POST'});location.href='/'};
async function load(){try{[me,groups]=await Promise.all([api('/api/profile'),api('/api/groups')]);scope=scope&&groups.some(g=>g.scope_id===scope)?scope:(groups[0]?.scope_id||'');document.getElementById('user-label').textContent=me.display_name||me.username;document.getElementById('profile-username').value=me.username||'';document.getElementById('profile-name').value=me.display_name||'';document.getElementById('profile-email').value=me.email||'';setupGroups();await loadGroup()}catch(e){document.getElementById('user-label').textContent=e.message}}load();
</script></body></html>"""


HOME_PAGE = r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Joker QQ 官方机器人</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#eff8ff;background:#081728}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 84% 9%,#187e93 0,#0b263e 30%,transparent 54%),linear-gradient(135deg,#061426,#0d2038 65%,#102847)}.wrap{max-width:1160px;margin:auto;padding:26px 30px 56px}.top{display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;gap:11px;align-items:center;font-weight:800}.mark{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:#23c2b8;color:#062126}.top span{color:#a7bfdb;font-size:13px}.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:36px;align-items:center;padding:100px 0 70px}.eyebrow{color:#73e0d5;font-size:13px;letter-spacing:1.5px}.hero h1{font-size:clamp(38px,5.4vw,66px);line-height:1.06;margin:16px 0}.hero p{color:#b8cbe2;font-size:17px;line-height:1.9;max-width:640px}.button{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;background:#22c2b8;color:#062126;padding:13px 19px;border-radius:8px;font-weight:800;margin-top:20px}.summary{border:1px solid #355474;background:#102742c7;border-radius:14px;padding:22px;box-shadow:0 22px 55px #0006}.summary strong{font-size:16px}.step{display:flex;gap:12px;padding:15px 0;border-bottom:1px solid #294968}.step:last-child{border:0}.num{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:99px;background:#1d5165;color:#8ef2e8;font-size:12px}.step span{display:block;color:#adc4dd;font-size:13px;line-height:1.6;margin-top:4px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{border:1px solid #315372;background:#112942b8;border-radius:12px;padding:20px}.card strong{display:block;margin-bottom:9px}.card p{margin:0;color:#afc4dc;font-size:13px;line-height:1.7}.foot{color:#8da6c2;font-size:12px;margin-top:35px}@media(max-width:760px){.wrap{padding:21px}.hero{grid-template-columns:1fr;padding:65px 0 46px}.cards{grid-template-columns:1fr}.summary{order:-1}}
</style></head><body><main class="wrap"><header class="top"><div class="brand"><div class="mark">J</div>Joker QQ</div><span>QQ 官方机器人群管服务</span></header><section class="hero"><div><div class="eyebrow">OFFICIAL QQ BOT CONSOLE</div><h1>只配置自己的群，<br>每个功能都有位置。</h1><p>从群授权、自动回复到关键词审核，全部由 QQ 官方机器人接口执行。管理员统一管理用户、卡密、邮件和服务；分群用户只管理自己绑定的官方群。</p><a class="button" href="__USER_PATH__">进入用户中心</a></div><aside class="summary"><strong>开始使用</strong><div class="step"><div class="num">01</div><div>使用用户注册卡创建账号<span>注册时必须验证邮箱。</span></div></div><div class="step"><div class="num">02</div><div>输入群授权卡绑定官方群<span>卡密创建时不预先绑定群。</span></div></div><div class="step"><div class="num">03</div><div>按导航设置当前群功能<span>每项群管功能均有独立页面。</span></div></div></aside></section><section class="cards"><article class="card"><strong>独立群配置</strong><p>用户只会看到已授权的群，配置和数据与其他分群隔离。</p></article><article class="card"><strong>官方接口执行</strong><p>禁言、踢出、黑名单等操作通过 QQ 官方机器人接口完成。</p></article><article class="card"><strong>邮件验证注册</strong><p>用户注册需接收并填写邮箱验证码，避免无效账号占用卡密。</p></article></section><p class="foot">Joker QQ 官方机器人控制台</p></main></body></html>"""


AUTH_PAGE = r"""<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Joker QQ 登录</title><style>
:root{font-family:"Microsoft YaHei",Arial,sans-serif;color:#eaf3ff;background:#09182a}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(circle at 10% 8%,#196c84 0,#0b263d 34%,transparent 62%),linear-gradient(135deg,#071426,#102b48);display:grid;place-items:center;padding:24px}.shell{width:min(970px,100%);min-height:590px;display:grid;grid-template-columns:.9fr 1.1fr;border:1px solid #345575;border-radius:16px;overflow:hidden;background:#10243cd9;box-shadow:0 30px 70px #0008}.intro{padding:52px 43px;background:linear-gradient(155deg,#0b2942,#0d1c34);display:flex;flex-direction:column}.mark{width:42px;height:42px;display:grid;place-items:center;border-radius:11px;background:#22c2b8;color:#062126;font-weight:800}.intro h1{font-size:38px;line-height:1.12;margin:40px 0 14px}.intro p{color:#b7cae2;line-height:1.8;margin:0}.points{margin-top:auto;display:grid;gap:12px}.point{padding:11px 13px;border:1px solid #315372;border-radius:8px;color:#c9dded;font-size:13px}.panel{padding:46px 48px;background:#0f2036}.eyebrow{color:#75e1d5;font-size:12px;letter-spacing:1.3px}.panel h2{font-size:25px;margin:10px 0 6px}.sub{color:#9ab0ca;font-size:13px;line-height:1.6;margin:0 0 21px}.tabs{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:18px}.tabs button{border:1px solid #325370;background:#132a45;color:#b9cce0;border-radius:7px;padding:10px;cursor:pointer;font:inherit}.tabs button.active{background:#1d5a68;color:#e9fffc;border-color:#22c2b8}.form{display:grid;gap:12px}label{display:grid;gap:6px;color:#aac0d8;font-size:12px}input{width:100%;border:1px solid #355574;border-radius:7px;background:#0a192b;color:#edf7ff;padding:11px;font:inherit}.code-row{display:grid;grid-template-columns:1fr auto;gap:8px}.button{border:1px solid #22c2b8;background:#22c2b8;border-radius:7px;color:#052126;padding:11px;font:inherit;font-weight:800;cursor:pointer}.button.secondary{background:#17304b;color:#d9e7f5;border-color:#365473}.button:disabled{opacity:.55;cursor:not-allowed}.message{font-size:13px;min-height:20px;color:#ffb8b8;margin:0}.message.ok{color:#85edc8}.hint{font-size:12px;color:#91a9c6;line-height:1.6;margin:2px 0 0}@media(max-width:760px){.shell{grid-template-columns:1fr;max-width:520px}.intro{display:none}.panel{padding:34px 25px}}@media(max-width:420px){body{padding:12px}.panel{padding:28px 19px}.code-row{grid-template-columns:1fr}}
</style></head><body><main class="shell"><section class="intro"><div class="mark">J</div><h1>群管理，<br>各自独立。</h1><p>管理员配置全局服务；分群用户通过授权卡绑定自己的官方群，并单独保存功能设置。</p><div class="points"><div class="point">邮箱验证码注册，避免无效账号占用卡密</div><div class="point">群授权卡创建时不绑定任何群</div><div class="point">每项群管功能都在独立导航中设置</div></div></section><section class="panel"><div class="eyebrow">JOKER QQ CONSOLE</div><h2>__LOGIN_LABEL__</h2><p class="sub" id="form-subtitle">使用账号和密码进入控制台。</p><div class="tabs"><button class="active" id="login-tab">登录</button><button id="register-tab">注册账号</button></div><form class="form" id="login-form"><label>账号或邮箱<input id="login-username" autocomplete="username" autofocus></label><label>密码<input id="login-password" type="password" autocomplete="current-password"></label><button class="button" type="submit">登录</button><button class="button secondary" type="button" id="token-login">使用访问令牌</button></form><form class="form" id="register-form" hidden><label>用户注册卡<input id="register-card" placeholder="JOKER-XXXXXXXXXX"></label><label>账号<input id="register-username" autocomplete="username"></label><label>邮箱<input id="register-email" type="email" autocomplete="email" placeholder="用于接收验证码"></label><div class="code-row"><label>邮箱验证码<input id="register-code" inputmode="numeric" maxlength="6" placeholder="6 位验证码"></label><button class="button secondary" type="button" id="send-code">发送验证码</button></div><label>密码<input id="register-password" type="password" autocomplete="new-password" placeholder="至少 6 位"></label><button class="button" type="submit">验证邮箱并注册</button><p class="hint">验证码 10 分钟内有效；发送后请检查收件箱及垃圾邮件。</p></form><p id="auth-message" class="message" aria-live="polite"></p></section></main><script>
const audience='__AUTH_AUDIENCE__',loginEndpoint='__LOGIN_ENDPOINT__',registerEndpoint='__REGISTER_ENDPOINT__',codeEndpoint='__REGISTER_CODE_ENDPOINT__',adminPath='__ADMIN_PATH__';const loginTab=document.getElementById('login-tab'),registerTab=document.getElementById('register-tab'),loginForm=document.getElementById('login-form'),registerForm=document.getElementById('register-form'),message=document.getElementById('auth-message'),subtitle=document.getElementById('form-subtitle'),sendCode=document.getElementById('send-code');const show=(mode)=>{const register=mode==='register';loginForm.hidden=register;registerForm.hidden=!register;loginTab.classList.toggle('active',!register);registerTab.classList.toggle('active',register);subtitle.textContent=register?'填写注册卡并完成邮箱验证后创建账号。':'使用账号或邮箱登录控制台。';message.textContent='';message.classList.remove('ok')};if(audience==='admin'){registerTab.hidden=true;registerForm.hidden=true;document.getElementById('token-login').hidden=false}else document.getElementById('token-login').hidden=true;loginTab.onclick=()=>show('login');registerTab.onclick=()=>show('register');const request=async(url,data)=>{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'操作失败');return d};const notice=(text,ok=false)=>{message.textContent=text;message.classList.toggle('ok',ok)};loginForm.onsubmit=async e=>{e.preventDefault();try{const r=await request(loginEndpoint,{username:document.getElementById('login-username').value.trim(),password:document.getElementById('login-password').value});location.href=r.redirect}catch(err){notice(err.message)}};document.getElementById('token-login').onclick=()=>{const token=prompt('输入访问令牌');if(token)location.href='/?token='+encodeURIComponent(token)};sendCode.onclick=async()=>{const email=document.getElementById('register-email').value.trim();if(!email)return notice('请先填写邮箱');sendCode.disabled=true;try{const r=await request(codeEndpoint,{email});notice(r.message||'验证码已发送',true)}catch(err){notice(err.message)}finally{setTimeout(()=>sendCode.disabled=false,3000)}};registerForm.onsubmit=async e=>{e.preventDefault();try{const r=await request(registerEndpoint,{card_code:document.getElementById('register-card').value.trim(),username:document.getElementById('register-username').value.trim(),email:document.getElementById('register-email').value.trim(),verification_code:document.getElementById('register-code').value.trim(),password:document.getElementById('register-password').value});location.href=r.redirect}catch(err){notice(err.message)}};
</script></body></html>"""
